import sys
from math import gcd

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t = int(next(iterator))
    except StopIteration:
        return

    results = []

    for _ in range(t):
        try:
            n = int(next(iterator))
            s = next(iterator)
        except StopIteration:
            break

        if len(s) != n:
            s = s.ljust(n, '?')

        v_pos = [i for i, c in enumerate(s) if c == 'V']
        k_pos = [i for i, c in enumerate(s) if c == '?']

        possible_periods = set()

        if not v_pos and not k_pos:
            pass
        else:
            for d in range(1, n + 1):
                valid = True
                for i in range(d, n):
                    if s[i] != '?' and s[i - d] != '?':
                        if s[i] != s[i - d]:
                            valid = False
                            break
                if valid:
                    possible_periods.add(d)

        sorted_periods = sorted(possible_periods)
        results.append(str(len(sorted_periods)))
        results.append(" ".join(map(str, sorted_periods)))

    print("\n".join(results))

if __name__ == "__main__":
    solve()
